const float delta = 0.015;
const int steps=80;
float height(vec2 uv){
return 1.0-texture(iChannel0,uv+0.5).r;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec3 uv = vec3(fragCoord/iResolution.xy-0.5,0.0);
    vec3 cam=vec3(iTime/8.0,0.0,sin(iTime/2.0)+1.2);

    vec3 toSurface=cam-uv;

    uv.z-=cam.z;

    uv.xy=uv.xy*uv.z;
    uv.xy-=cam.xy;
    float lax=0.0;
    vec2 deltat=(fragCoord/iResolution.xy-0.5);

      float d0 = 0.0;
    float d1 = 0.0;
    float d2 = 0.0;

   for ( int i = 0; i < steps; i++ )
	{
		uv.xy += (deltat / float(steps) *0.05) / -uv.z;

        d0 = height(uv.xy);
        d1 = height(uv.xy + vec2(delta, 0.0));
        d2 = height(uv.xy + vec2(0.0, delta));

		if (1.-d0 < float(i) / float(steps))
		{
			break;
        }
	}

    vec3 off=vec3(vec2(1.0,1.0)/iResolution.xy,0.0);
    vec2 grad=vec2(d0-d1,d0-d2);
    vec3 norm=vec3(grad,1.2);
    norm=normalize(norm);
    toSurface=normalize(toSurface);
    float lamb=dot(normalize(vec3(-deltat,-uv.z)),norm);
    fragColor.rgb=vec3(lamb*0.5);
    lamb=dot(vec3(0.0,0.0,1.0),normalize(reflect(vec3(deltat,1.0),norm)));
    lamb*=lamb;
    lamb*=lamb;
    lamb*=lamb;
    lamb*=lamb;

    fragColor.rgb+=vec3(lamb*0.6);
    fragColor.rgb=mix(fragColor.rgb,texture(iChannel1,reflect(vec3(deltat,1.0),norm)).rgb,0.3);
    fragColor.a=1.0;
}

vec2 noise(vec2 uv){
return texture(iChannel0,uv).rg;
}
float fbm(vec2 uv){
float ou=0.0;
float scale=1.0;
for(float i=0.0;i<6.0;i++){
ou+=texture(iChannel0,noise(uv*scale)).r/scale;
scale*=2.0;
}
ou/=3.0;
return ou;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = fragCoord/iResolution.xy;

   fragColor.rgb=vec3(fbm(uv/28.0));
   fragColor.a=1.0;
}
